class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    PlatformRequest<false> platformsMinimal() const {
        return PlatformRequest<false>(binding_.get(), true);
    }

    PlatformRequest<false> platforms() const {
        return PlatformRequest<false>(binding_.get());
    }

    PlatformRequest<false> platformsWithChildren() const {
        return PlatformRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    OwnerRequest<false> ownersMinimal() const {
        return OwnerRequest<false>(binding_.get(), true);
    }

    OwnerRequest<false> owners() const {
        return OwnerRequest<false>(binding_.get());
    }

    OwnerRequest<false> ownersWithChildren() const {
        return OwnerRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    EntryRequest<false> entriesMinimal() const {
        return EntryRequest<false>(binding_.get(), true);
    }

    EntryRequest<false> entries() const {
        return EntryRequest<false>(binding_.get());
    }

    EntryRequest<false> entriesWithChildren() const {
        return EntryRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    ProfileRequest<false> profilesMinimal() const {
        return ProfileRequest<false>(binding_.get(), true);
    }

    ProfileRequest<false> profiles() const {
        return ProfileRequest<false>(binding_.get());
    }

    ProfileRequest<false> profilesWithChildren() const {
        return ProfileRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
